const uint N = rows * I;
const uint base = thread_position_in_grid.x * 8;
if (base >= N) return;
if (base + 8 <= N) {
    uint4 ga = ld16(g + base);
    uint4 ua = ld16(u + base);
    float4 a0 = float4(as_type<half4>(ga.xy)), a1 = float4(as_type<half4>(ga.zw));
    float4 b0 = float4(as_type<half4>(ua.xy)), b1 = float4(as_type<half4>(ua.zw));
    uint4 o;
    o.xy = as_type<uint2>(half4(swg(a0, b0)));
    o.zw = as_type<uint2>(half4(swg(a1, b1)));
    st16(out + base, o);
} else {
    for (uint i = base; i < N; ++i) {
        float a = float(g[i]);
        float e = metal::fast::exp2(metal::min(-a * 1.4426950408889634f, 100.0f));
        out[i] = half(a * metal::fast::divide(1.0f, 1.0f + e) * float(u[i]));
    }
}

